    18	import static br.com.marealta.pousada.domain.DomainException.Kind.RESERVATION_NOT_FOUND;
    19	
    20	public final class Api {
    21	
    22	    private final ReservationService service;
    23	    private final RoomCatalog rooms;
    24	    private final MessageLog messages;
    25	    private final ObjectMapper mapper = new ObjectMapper()
    26	            .registerModule(new JavaTimeModule())
    27	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
    28	    private final RequestParser parser = new RequestParser(mapper);
    29	
    30	    public Api(ReservationService service, RoomCatalog rooms, MessageLog messages) {
    31	        this.service = service;
    32	        this.rooms = rooms;
    33	        this.messages = messages;
    34	    }
    35	
    36	    public Javalin create() {
    37	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    38	
    39	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.kind().httpStatus(), e.kind().name(), e.getMessage()));
    40	        app.exception(Exception.class, (e, ctx) -> {
    41	            e.printStackTrace();
    42	            error(ctx, 500, "INTERNAL_ERROR", "erro interno");
    43	        });
    44	
    45	        app.get("/rooms", ctx -> json(ctx, 200, rooms.all().stream().map(RoomView::of).toList()));
    46	        app.post("/reservations", ctx -> json(ctx, 201,
    47	                ReservationView.of(service.create(parser.reservation(ctx.body())))));
    48	        app.get("/reservations/{id}", ctx -> json(ctx, 200, ReservationView.of(service.get(id(ctx)))));
    49	        app.post("/reservations/{id}/confirmation", ctx -> json(ctx, 200, ReservationView.of(service.confirm(id(ctx)))));
    50	        app.post("/reservations/{id}/cancellation", ctx -> json(ctx, 200, ReservationView.of(service.cancel(id(ctx)))));
    51	        app.post("/reservations/{id}/check-in", ctx -> json(ctx, 200, ReservationView.of(service.checkIn(id(ctx)))));
    52	        app.post("/reservations/{id}/check-out", ctx -> json(ctx, 200, service.checkOut(id(ctx))));
    53	        app.get("/reservations/{id}/document", ctx -> json(ctx, 200, service.document(id(ctx))));
    54	        app.get("/messages", ctx -> json(ctx, 200, messages.all()));
    55	        app.get("/reports/occupancy", ctx -> csv(ctx, OccupancyReport.render(
    56	                parser.date(ctx.queryParam("date"), "date"), service.all(), rooms)));
    57	        app.get("/reports/revenue", ctx -> csv(ctx, RevenueReport.render(
    58	                parser.month(ctx.queryParam("month")), service.all())));
    59	        return app;
    60	    }
    61	
    62	    private long id(Context ctx) {
    63	        try {
    64	            return Long.parseLong(ctx.pathParam("id"));
    65	        } catch (NumberFormatException e) {
    66	            throw new DomainException(RESERVATION_NOT_FOUND, "reserva inexistente");
    67	        }
    68	    }
    69	
    70	    private void json(Context ctx, int status, Object body) throws Exception {
    71	        ctx.status(status).contentType("application/json").result(mapper.writeValueAsString(body));
    72	    }
    73	
    74	    private void csv(Context ctx, String body) {
    75	        ctx.status(200).contentType("text/csv; charset=utf-8").result(body);
    76	    }
    77	
    78	    private void error(Context ctx, int status, String code, String message) {
    79	        try {
    80	            json(ctx, status, Map.of("error", code, "message", message));
    81	        } catch (Exception e) {
    82	            ctx.status(500);
    83	        }
    84	    }
    85	}
