     1	package br.com.marealta.pousada.web;
     2	
     3	import java.time.LocalDate;
     4	import java.time.YearMonth;
     5	import java.time.format.DateTimeParseException;
     6	
     7	import com.fasterxml.jackson.core.JsonProcessingException;
     8	import com.fasterxml.jackson.databind.JsonNode;
     9	import com.fasterxml.jackson.databind.ObjectMapper;
    10	
    11	import br.com.marealta.pousada.domain.DomainException;
    12	import br.com.marealta.pousada.domain.Guest;
    13	import br.com.marealta.pousada.domain.NewReservation;
    14	import br.com.marealta.pousada.domain.RatePlan;
    15	
    16	import static br.com.marealta.pousada.domain.DomainException.Kind.INVALID_REQUEST;
    17	
    18	final class RequestParser {
    19	
    20	    private final ObjectMapper mapper;
    21	
    22	    RequestParser(ObjectMapper mapper) {
    23	        this.mapper = mapper;
    24	    }
    25	
    26	    NewReservation reservation(String body) {
    27	        JsonNode json;
    28	        try {
    29	            json = mapper.readTree(body);
    30	        } catch (JsonProcessingException e) {
    31	            throw invalid("o corpo não é um JSON válido");
    32	        }
    33	        if (json == null || !json.isObject()) {
    34	            throw invalid("o corpo deve ser um objeto JSON");
    35	        }
    36	        return new NewReservation(
    37	                integer(json, "roomNumber"),
    38	                new Guest(text(json, "guestName"), text(json, "guestEmail"), text(json, "guestCpf")),
    39	                date(text(json, "checkIn"), "checkIn"),
    40	                date(text(json, "checkOut"), "checkOut"),
    41	                integer(json, "guests"),
    42	                ratePlan(text(json, "ratePlan")));
    43	    }
    44	
    45	    LocalDate date(String value, String field) {
    46	        if (value == null || value.isBlank()) {
    47	            throw invalid("falta o campo " + field);
    48	        }
    49	        try {
    50	            return LocalDate.parse(value);
    51	        } catch (DateTimeParseException e) {
    52	            throw invalid("data inválida em " + field);
    53	        }
    54	    }
    55	
    56	    YearMonth month(String value) {
    57	        if (value == null || value.isBlank()) {
    58	            throw invalid("falta o parâmetro month");
    59	        }
    60	        try {
    61	            return YearMonth.parse(value);
    62	        } catch (DateTimeParseException e) {
    63	            throw invalid("mês inválido");
    64	        }
    65	    }
    66	
    67	    private RatePlan ratePlan(String value) {
    68	        try {
    69	            return RatePlan.valueOf(value);
    70	        } catch (IllegalArgumentException e) {
    71	            throw invalid("plano de tarifa inválido");
    72	        }
    73	    }
    74	
    75	    private String text(JsonNode json, String field) {
    76	        JsonNode node = json.get(field);
    77	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    78	            throw invalid("campo ausente ou inválido: " + field);
    79	        }
    80	        return node.asText();
    81	    }
    82	
    83	    private int integer(JsonNode json, String field) {
    84	        JsonNode node = json.get(field);
    85	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    86	            throw invalid("campo ausente ou inválido: " + field);
    87	        }
    88	        return node.asInt();
    89	    }
    90	
    91	    private DomainException invalid(String message) {
    92	        return new DomainException(INVALID_REQUEST, message);
    93	    }
    94	}
