     6	import static br.com.marealta.pousada.domain.ReservationStatus.*;
     7	
     8	public class Reservation {
     9	
    10	    private final long id;
    11	    private final Room room;
    12	    private final Guest guest;
    13	    private final LocalDate checkIn;
    14	    private final LocalDate checkOut;
    15	    private final int guests;
    16	    private final RatePlan ratePlan;
    17	    private final Quote quote;
    18	    private ReservationStatus status;
    19	    private BigDecimal amountPaid;
    20	    private BigDecimal refund;
    21	
    22	    public Reservation(long id, Room room, Guest guest, LocalDate checkIn, LocalDate checkOut, int guests,
    23	                       RatePlan ratePlan, Quote quote, ReservationStatus status,
    24	                       BigDecimal amountPaid, BigDecimal refund) {
    25	        this.id = id;
    26	        this.room = room;
    27	        this.guest = guest;
    28	        this.checkIn = checkIn;
    29	        this.checkOut = checkOut;
    30	        this.guests = guests;
    31	        this.ratePlan = ratePlan;
    32	        this.quote = quote;
    33	        this.status = status;
    34	        this.amountPaid = amountPaid;
    35	        this.refund = refund;
    36	    }
    37	
    38	    public static Reservation pending(long id, Room room, Guest guest, LocalDate checkIn, LocalDate checkOut,
    39	                                      int guests, RatePlan ratePlan) {
    40	        Quote quote = Quote.of(room, checkIn, checkOut, ratePlan);
    41	        return new Reservation(id, room, guest, checkIn, checkOut, guests, ratePlan, quote, PENDING,
    42	                Money.ZERO, null);
    43	    }
    44	
    45	    /** Guarda a mesma reserva com outro número (o que o banco atribuiu). */
    46	    public Reservation withId(long newId) {
    47	        return new Reservation(newId, room, guest, checkIn, checkOut, guests, ratePlan, quote, status,
    48	                amountPaid, refund);
    49	    }
    50	
    51	    public void confirm() {
    52	        require(status == PENDING, "só é possível confirmar uma reserva pendente");
    53	        status = CONFIRMED;
    54	        amountPaid = quote.total();
    55	    }
    56	
    57	    public void startStay() {
    58	        require(status == CONFIRMED, "só é possível fazer check-in de uma reserva confirmada");
    59	        status = CHECKED_IN;
    60	    }
    61	
    62	    public void endStay() {
    63	        require(status == CHECKED_IN, "só é possível fazer check-out de uma reserva com check-in");
    64	        status = CHECKED_OUT;
    65	    }
    66	
    67	    public void cancel() {
    68	        require(status == PENDING || status == CONFIRMED,
    69	                "só é possível cancelar uma reserva pendente ou confirmada");
    70	        refund = status == CONFIRMED ? ratePlan.refundFor(amountPaid) : Money.ZERO;
    71	        status = CANCELLED;
    72	    }
    73	
    74	    private void require(boolean allowed, String message) {
    75	        if (!allowed) {
    76	            throw new DomainException(DomainException.Kind.OPERATION_NOT_ALLOWED, message);
    77	        }
    78	    }
    79	
    80	    /** O que ficou com a pousada: pago menos devolvido. */
    81	    public BigDecimal retainedAmount() {
    82	        return refund == null ? amountPaid : amountPaid.subtract(refund);
    83	    }
    84	
    85	    public boolean occupiesNight(LocalDate night) {
    86	        return !night.isBefore(checkIn) && night.isBefore(checkOut);
    87	    }
    88	
    89	    public long id() { return id; }
    90	    public Room room() { return room; }
    91	    public Guest guest() { return guest; }
    92	    public LocalDate checkIn() { return checkIn; }
    93	    public LocalDate checkOut() { return checkOut; }
    94	    public int guests() { return guests; }
    95	    public RatePlan ratePlan() { return ratePlan; }
    96	    public Quote quote() { return quote; }
    97	    public ReservationStatus status() { return status; }
    98	    public BigDecimal amountPaid() { return amountPaid; }
    99	    public BigDecimal refund() { return refund; }
   100	}
