     1	package br.com.marealta.pousada.domain;
     2	
     3	import java.util.List;
     4	import java.util.concurrent.locks.ReentrantLock;
     5	
     6	import static br.com.marealta.pousada.domain.DomainException.Kind.*;
     7	
     8	public class ReservationService {
     9	
    10	    private final ReservationRepository repository;
    11	    private final RoomCatalog rooms;
    12	    private final List<ReservationListener> listeners;
    13	    private final ReentrantLock lock = new ReentrantLock();
    14	
    15	    public ReservationService(ReservationRepository repository, RoomCatalog rooms,
    16	                              List<ReservationListener> listeners) {
    17	        this.repository = repository;
    18	        this.rooms = rooms;
    19	        this.listeners = List.copyOf(listeners);
    20	    }
    21	
    22	    public Reservation create(NewReservation request) {
    23	        if (!request.checkOut().isAfter(request.checkIn())) {
    24	            throw new DomainException(INVALID_REQUEST, "a saída deve ser depois da entrada");
    25	        }
    26	        if (request.guests() < 1) {
    27	            throw new DomainException(INVALID_REQUEST, "é preciso ao menos um hóspede");
    28	        }
    29	        Room room = rooms.find(request.roomNumber())
    30	                .orElseThrow(() -> new DomainException(ROOM_NOT_FOUND, "quarto inexistente"));
    31	        if (request.guests() > room.capacity()) {
    32	            throw new DomainException(CAPACITY_EXCEEDED, "o quarto comporta no máximo " + room.capacity());
    33	        }
    34	        lock.lock();
    35	        try {
    36	            if (repository.existsOverlap(room.number(), request.checkIn(), request.checkOut())) {
    37	                throw new DomainException(ROOM_UNAVAILABLE, "quarto já reservado em alguma das noites");
    38	            }
    39	            return repository.insert(Reservation.pending(0, room, request.guest(), request.checkIn(),
    40	                    request.checkOut(), request.guests(), request.ratePlan()));
    41	        } finally {
    42	            lock.unlock();
    43	        }
    44	    }
    45	
    46	    public Reservation get(long id) {
    47	        return repository.find(id)
    48	                .orElseThrow(() -> new DomainException(RESERVATION_NOT_FOUND, "reserva inexistente"));
    49	    }
    50	
    51	    public Reservation confirm(long id) {
    52	        Reservation reservation = change(id, Reservation::confirm);
    53	        listeners.forEach(l -> l.onConfirmed(reservation));
    54	        return reservation;
    55	    }
    56	
    57	    public Reservation cancel(long id) {
    58	        ReservationStatus[] previous = new ReservationStatus[1];
    59	        Reservation reservation = change(id, r -> {
    60	            previous[0] = r.status();
    61	            r.cancel();
    62	        });
    63	        listeners.forEach(l -> l.onCancelled(reservation, previous[0]));
    64	        return reservation;
    65	    }
    66	
    67	    public Reservation checkIn(long id) {
    68	        return change(id, Reservation::startStay);
    69	    }
    70	
    71	    public Receipt checkOut(long id) {
    72	        return Receipt.of(change(id, Reservation::endStay));
    73	    }
    74	
    75	    /** Segunda via do comprovante: só existe para reserva paga. */
    76	    public Receipt document(long id) {
    77	        Reservation reservation = get(id);
    78	        if (!reservation.status().isPaid()) {
    79	            throw new DomainException(OPERATION_NOT_ALLOWED, "a reserva não tem pagamento");
    80	        }
    81	        return Receipt.of(reservation);
    82	    }
    83	
    84	    public List<Reservation> all() {
    85	        return repository.findAll();
    86	    }
    87	
    88	    private Reservation change(long id, java.util.function.Consumer<Reservation> action) {
    89	        lock.lock();
    90	        try {
    91	            Reservation reservation = get(id);
    92	            action.accept(reservation);
    93	            repository.update(reservation);
    94	            return reservation;
    95	        } finally {
    96	            lock.unlock();
    97	        }
    98	    }
    99	}
