     5	
     6	public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     7	
     8	    private static final BigDecimal HIGH_SEASON_MARKUP = new BigDecimal("1.20");
     9	
    10	    public static Quote of(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    11	        BigDecimal subtotal = Money.ZERO;
    12	        int nights = 0;
    13	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    14	            subtotal = subtotal.add(nightPrice(room, night));
    15	            nights++;
    16	        }
    17	        BigDecimal discount = plan.discountOn(subtotal);
    18	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    19	    }
    20	
    21	    private static BigDecimal nightPrice(Room room, LocalDate night) {
    22	        BigDecimal rate = room.nightlyRate();
    23	        return Money.round(isHighSeason(night) ? rate.multiply(HIGH_SEASON_MARKUP) : rate);
    24	    }
    25	
    26	    /** De 15 de dezembro ao fim de fevereiro, e julho inteiro. */
    27	    public static boolean isHighSeason(LocalDate day) {
    28	        return switch (day.getMonth()) {
    29	            case JANUARY, FEBRUARY, JULY -> true;
    30	            case DECEMBER -> day.getDayOfMonth() >= 15;
    31	            default -> false;
    32	        };
    33	    }
    34	}
