    14	        public Reservation insert(Reservation draft) {
    15	            Reservation saved = draft.withId(data.size() + 1);
    16	            data.put(saved.id(), saved);
    17	            return saved;
    18	        }
    19	        public void update(Reservation r) { data.put(r.id(), r); }
    20	        public Optional<Reservation> find(long id) { return Optional.ofNullable(data.get(id)); }
    21	        public List<Reservation> findAll() { return new ArrayList<>(data.values()); }
    22	        public boolean existsOverlap(int room, LocalDate in, LocalDate out) {
    23	            return data.values().stream().anyMatch(r -> r.room().number() == room
    24	                    && r.status() != ReservationStatus.CANCELLED
    25	                    && r.checkIn().isBefore(out) && r.checkOut().isAfter(in));
    26	        }
    27	    }
