     9	final class InMemory {
    10	
    11	    static final class Reservations implements ReservationRepository {
    12	        private final Map<Long, Reservation> data = new TreeMap<>();
    13	
    14	        public Reservation insert(Reservation draft) {
    15	            Reservation saved = draft.withId(data.size() + 1);
    16	            data.put(saved.id(), saved);
    17	            return saved;
    18	        }
    19	        public void update(Reservation r) { data.put(r.id(), r); }
    20	        public Optional<Reservation> find(long id) { return Optional.ofNullable(data.get(id)); }
    21	        public List<Reservation> findAll() { return new ArrayList<>(data.values()); }
    22	        public boolean existsOverlap(int room, LocalDate in, LocalDate out) {
    23	            return data.values().stream().anyMatch(r -> r.room().number() == room
    24	                    && r.status() != ReservationStatus.CANCELLED
    25	                    && r.checkIn().isBefore(out) && r.checkOut().isAfter(in));
    26	        }
    27	    }
    28	
    29	    static final class Messages implements MessageLog {
    30	        final List<Message> sent = new ArrayList<>();
    31	
    32	        public Message send(Channel channel, String to, String subject, String body) {
    33	            Message m = new Message(sent.size() + 1, channel, to, subject, body);
    34	            sent.add(m);
    35	            return m;
    36	        }
    37	        public List<Message> all() { return sent; }
    38	    }
    39	
    40	    static List<ReservationListener> listeners(MessageLog log) {
    41	        return List.of(new GuestConfirmationNotice(log),
    42	                new HousekeepingNotice(log, "governanca@pousadamarealta.com.br"),
    43	                new FinanceNotice(log, "financeiro@pousadamarealta.com.br"));
